import type { OpenAiCompletionTokensDetails } from './open-ai-completion-tokens-details';
import type { OpenAiPromptTokensDetails } from './open-ai-prompt-tokens-details';
import type { ProviderJsonValue } from './provider-json-value';

/** OpenAI-compatible open ai token usage schema exposed by Claw Router. */
export interface OpenAiTokenUsage {
  /** Number of output tokens generated by the model. */
  completion_tokens: number;
  /** Completion tokens details field on the open ai token usage, using the open ai completion tokens details module. */
  completion_tokens_details?: OpenAiCompletionTokensDetails;
  /** Number of input tokens billed for the request. */
  prompt_tokens: number;
  /** Prompt tokens details field on the open ai token usage, using the open ai prompt tokens details module. */
  prompt_tokens_details?: OpenAiPromptTokensDetails;
  /** Total input and output token count. */
  total_tokens: number;
}
